@pytest.mark.parametrize("case", CASES, ids=[c["id"] for c in CASES])
def test_matches_over_imported_types(run, workdir, case):
    """CATCHES: qualified constructor patterns, or-patterns, guards with and/or, nested
    and list patterns, record patterns or exhaustiveness over imported types that
    check, lower (default or --native) or evaluate differently from the reference."""
    S.check(run, workdir, case, __file__)
